perl -0777 -e '
use strict; use warnings;
my $ttl = do { local $/; <STDIN> };
my (%course_dept, %dept_uni, %uni_country, %student_courses, %student_grad, %prof);
while ($ttl =~ /uni:(\w+)\s+a\s+uni:Course\s*;\s*uni:isTaughtIn\s+uni:(\w+)\s*\./g) { $course_dept{$1} = $2 }
while ($ttl =~ /uni:(\w+)\s+a\s+uni:Department\s*;\s*uni:belongsTo\s+uni:(\w+)\s*\./g) { $dept_uni{$1} = $2 }
while ($ttl =~ /uni:(\w+)\s+a\s+uni:University\s*;\s*uni:hasName\s+"[^"]+"\s*;\s*uni:locatedInCountry\s+"([A-Z]{2})"\s*\./g) { $uni_country{$1} = $2 }
while ($ttl =~ /uni:(Student\d+)\s+uni:isEnrolledIn\s+([^;]+);\s*uni:hasEnrollmentDate\s+"([^"]+)"\^\^xsd:date(?:\s*;\s*uni:hasGraduationDate\s+"([^"]+)"\^\^xsd:date)?\s*\./g) {
